CREATE TABLE studio_profile (id VARCHAR(64) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,name VARCHAR(160) NOT NULL,description TEXT NOT NULL,address VARCHAR(500) NOT NULL,phone VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enquiry (id VARCHAR(64) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,branch_id VARCHAR(64) NOT NULL,student_name VARCHAR(80) NOT NULL,phone VARCHAR(32) NOT NULL,age INT NOT NULL,source VARCHAR(120) NOT NULL,source_id VARCHAR(120) NOT NULL,referrer_id VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,assignee_id VARCHAR(64),reservation_id VARCHAR(64),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_enquiry_branch(tenant_id,branch_id,status),INDEX idx_enquiry_contact(branch_id,phone,created_at));
CREATE TABLE enquiry_followup (id VARCHAR(64) PRIMARY KEY,enquiry_id VARCHAR(64) NOT NULL,author_id VARCHAR(64) NOT NULL,note TEXT NOT NULL,status VARCHAR(32) NOT NULL,next_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_followup_enquiry(enquiry_id,created_at));
CREATE TABLE engagement_activity (id VARCHAR(64) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,branch_id VARCHAR(64) NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,starts_at TIMESTAMP NOT NULL,capacity INT NOT NULL,reserved INT NOT NULL DEFAULT 0,published BOOLEAN NOT NULL,INDEX idx_activity_branch(tenant_id,branch_id));
CREATE TABLE activity_signup (id VARCHAR(64) PRIMARY KEY,activity_id VARCHAR(64) NOT NULL,tenant_id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_signup(activity_id,user_id));
CREATE TABLE renewal_followup (id VARCHAR(64) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,branch_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,assignee_id VARCHAR(64) NOT NULL,note TEXT NOT NULL,next_at TIMESTAMP NULL,status VARCHAR(32) NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_renewal_branch(tenant_id,branch_id,status));
CREATE TABLE referral_reward (enquiry_id VARCHAR(64) PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,referrer_id VARCHAR(64) NOT NULL,enrollment_id VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,fulfillment_note VARCHAR(1000),fulfilled_by VARCHAR(64),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_reward_enrollment(enrollment_id));
